import re


def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """
    Parse INI-formatted text according to the specified dialect rules.

    Returns a dictionary mapping section names to dictionaries of key-value pairs.
    The DEFAULT section is not included in the result but its values are inherited.
    """
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    current_key: str | None = None

    for line in text.split('
'):
        left_stripped = line.lstrip()

        # Rule 3: Ignore empty lines and comment lines (; or # as first non-space char)
        if not left_stripped or left_stripped[0] in (';', '#'):
            current_key = None
            continue

        # Rule 1: Section headers [name] with optional surrounding whitespace
        sec_match = re.match(r'\s*\[\s*(.*?)\s*\]\s*$', line)
        if sec_match:
            section_name = sec_match.group(1)
            current_section = '__DEFAULT__' if section_name == 'DEFAULT' else section_name
            sections.setdefault(current_section, {})
            current_key = None
            continue

        # Rule 10: Key-value pair before any section header is an error
        if current_section is None:
            raise ValueError("Key-value pair encountered before any section header")

        # Rule 6: Continuation line (starts with whitespace, follows a key line)
        if line and line[0].isspace() and current_key is not None:
            sections[current_section][current_key] += '
' + line.strip()
            continue

        # Rule 2: Parse key = value or key : value (split on first = or :)
        eq_pos = line.find('=')
        colon_pos = line.find(':')

        if eq_pos == -1 and colon_pos == -1:
            raise ValueError(f"Malformed line (no '=' or ':' found): {line!r}")

        if eq_pos == -1:
            split_at = colon_pos
        elif colon_pos == -1:
            split_at = eq_pos
        else:
            split_at = min(eq_pos, colon_pos)

        key = line[:split_at].strip().lower()
        if not key:
            raise ValueError(f"Malformed line (empty key): {line!r}")

        raw_value = line[split_at + 1:]
        value = _parse_value(raw_value)

        # Rule 7: Later values overwrite earlier ones
        sections[current_section][key] = value
        current_key = key

    # Rule 8: Handle DEFAULT section inheritance
    default_keys = sections.pop('__DEFAULT__', {})

    result: dict[str, dict[str, str]] = {}
    for section_name, section_data in sections.items():
        merged = dict(default_keys)
        merged.update(section_data)
        result[section_name] = merged

    # Rule 9: Perform interpolation
    final_result: dict[str, dict[str, str]] = {}
    for section_name, section_data in result.items():
        final_result[section_name] = {}
        for key, value in section_data.items():
            final_result[section_name][key] = _interpolate(
                result, section_name, value, frozenset()
            )

    return final_result


def _parse_value(value_str: str) -> str:
    """
    Parse a value string handling quotes and inline comments.

    Rule 5: Double-quoted values keep contents exactly (quotes removed).
    Rule 4: Inline comments start at ' ;' or ' #' (not inside quotes).
    """
    value_str = value_str.lstrip()

    if not value_str:
        return ''

    # Rule 5: Quoted value - keep everything inside exactly
    if value_str[0] == '"':
        close_quote = value_str.find('"', 1)
        if close_quote == -1:
            return value_str[1:]
        return value_str[1:close_quote]

    # Rule 4: Unquoted value - look for inline comment (whitespace + ; or #)
    for i, ch in enumerate(value_str):
        if ch in (' ', '\t') and i + 1 < len(value_str) and value_str[i + 1] in (';', '#'):
            return value_str[:i].rstrip()

    return value_str.rstrip()


def _interpolate(
    sections: dict[str, dict[str, str]],
    current_section: str,
    value: str,
    visiting: frozenset
) -> str:
    """
    Recursively resolve ${...} interpolations.

    Rule 9: ${key} for same section, ${section:key} for cross-section.
    Raises KeyError for missing references, ValueError for cycles.
    """
    def replace_ref(match: re.Match) -> str:
        ref = match.group(1)

        if ':' in ref:
            target_section, target_key = ref.split(':', 1)
        else:
            target_section = current_section
            target_key = ref

        if target_section not in sections:
            raise KeyError(f"Referenced section '{target_section}' does not exist")
        if target_key not in sections[target_section]:
            raise KeyError(
                f"Referenced key '{target_key}' does not exist in section '{target_section}'"
            )

        ref_node = (target_section, target_key)
        if ref_node in visiting:
            raise ValueError(f"Circular interpolation reference detected: {ref_node}")

        return _interpolate(
            sections,
            target_section,
            sections[target_section][target_key],
            visiting | {ref_node}
        )

    return re.sub(r'\$\{([^}]+)\}', replace_ref, value)
